1	export interface Customer {
2	  yearsWithMHPCO: number;
3	}
4	
5	/** An item a customer brings to be insured, as the office records it. */
6	export interface Item {
7	  type: string;
8	  material?: string;
9	  cursed?: boolean;
10	  enchantment?: number;
11	}
12	
13	const PROCESSING_FEE = 5;
14	
15	/** MHPCO price list: the base premium the office charges for one insured main item. */
16	const MAIN_ITEM_BASE_PREMIUMS: Record<string, number> = {
17	  sword: 100,
18	  amulet: 60,
19	  staff: 80,
20	  potion: 40,
21	};
22	
23	/** Components are priced off a single uniform rate rather than a price-list row. */
24	const COMPONENT_TYPES = new Set(["rune", "moonstone"]);
25	const COMPONENT_BASE_PREMIUM = 25;
26	
27	function isComponentType(type: string): boolean {
28	  return COMPONENT_TYPES.has(type);
29	}
30	
31	/** The price-list base premium for one item of the given type. */
32	function catalogueBasePremiumOf(type: string): number {
33	  return isComponentType(type) ? COMPONENT_BASE_PREMIUM : MAIN_ITEM_BASE_PREMIUMS[type];
34	}
35	
36	const BLOCK_SIZE = 3;
37	const BLOCK_BASE_PREMIUM = 60;
38	
39	/** A policy's items of one and the same type -- what the office calls "alike". */
40	interface AlikeItems {
41	  type: string;
42	  items: Item[];
43	}
44	
45	/**
46	 * The office groups a policy's items into groups of alike items, because its
47	 * building-block offer is priced per group rather than per item. "Alike" means
48	 * the same item type.
49	 */
50	function groupAlikeItems(items: Item[]): AlikeItems[] {
51	  const groups = new Map<string, AlikeItems>();
52	  for (const item of items) {
53	    const group = groups.get(item.type);
54	    if (group === undefined) {
55	      groups.set(item.type, { type: item.type, items: [item] });
56	    } else {
57	      group.items.push(item);
58	    }
59	  }
60	  return [...groups.values()];
61	}
62	
63	/**
64	 * A building block of exactly 3 alike components is offered at a special base
65	 * premium instead of the catalogue rate; any other count is priced per component.
66	 */
67	function isBuildingBlock({ type, items }: AlikeItems): boolean {
68	  return isComponentType(type) && items.length === BLOCK_SIZE;
69	}
70	
71	/** Without an offer, the office simply charges the catalogue rate for every item. */
72	function catalogueRateBasePremiumOf({ type, items }: AlikeItems): number {
73	  return items.length * catalogueBasePremiumOf(type);
74	}
75	
76	/** What the office charges for one group of alike items covered by the same policy. */
77	function alikeItemsBasePremiumOf(alikeItems: AlikeItems): number {
78	  return isBuildingBlock(alikeItems)
79	    ? BLOCK_BASE_PREMIUM
80	    : catalogueRateBasePremiumOf(alikeItems);
81	}
82	
83	const HIGH_ENCHANTMENT_LEVEL = 5;
84	
85	function isCursed(item: Item): boolean {
86	  return item.cursed === true;
87	}
88	
89	/** The office considers an item highly enchanted from enchantment level 5 upwards. */
90	function isHighlyEnchanted(item: Item): boolean {
91	  return (item.enchantment ?? 0) >= HIGH_ENCHANTMENT_LEVEL;
92	}
93	
94	/**
95	 * One clause of the office's risk schedule: the risk it looks for in a single
96	 * item, and the surcharge it levies on that item's base premium when it finds it.
97	 */
98	interface ItemRiskClause {
99	  appliesTo: (item: Item) => boolean;
100	  surchargeRate: number;
101	}
102	
103	/** The office's schedule of item-specific risks, as written in its statutes. */
104	const ITEM_RISK_CLAUSES: ItemRiskClause[] = [
105	  { appliesTo: isCursed, surchargeRate: 0.5 },
106	  { appliesTo: isHighlyEnchanted, surchargeRate: 0.3 },
107	];
108	
109	/**
110	 * Item-specific risk surcharges are charged on the base premium of the affected
111	 * item alone, never on the policy total. An item that carries several risks is
112	 * surcharged for each of them, the office adding the rates together.
113	 */
114	function itemRiskSurchargeRateOf(item: Item): number {
115	  return ITEM_RISK_CLAUSES.filter((clause) => clause.appliesTo(item)).reduce(
116	    (rate, clause) => rate + clause.surchargeRate,
117	    0,
118	  );
119	}
120	
121	/**
122	 * How much of a group's base premium each alike item is held to carry. Group
123	 * offers such as the building block are priced per group, so the office has to
124	 * decide what an individual item inside a group is worth before it can charge an
125	 * item-specific surcharge on it. The office's reading: alike items are
126	 * interchangeable, so each carries an equal share of the group's base premium
127	 * (20 G each inside a 60 G block). Shares are kept as exact fractions.
128	 */
129	function apportionedBasePremiumOf(alikeItems: AlikeItems): number {
130	  return alikeItemsBasePremiumOf(alikeItems) / alikeItems.items.length;
131	}
132	
133	/** One item paired with the base premium the office holds it to carry. */
134	interface ItemBasePremium {
135	  item: Item;
136	  basePremium: number;
137	}
138	
139	/** What each item of a group contributes to the policy base premium. */
140	function itemBasePremiumsOf(alikeItems: AlikeItems): ItemBasePremium[] {
141	  const basePremium = apportionedBasePremiumOf(alikeItems);
142	  return alikeItems.items.map((item) => ({ item, basePremium }));
143	}
144	
145	/** What an item's own risks add to its base premium, in G. */
146	function itemRiskSurchargeOf({ item, basePremium }: ItemBasePremium): number {
147	  return basePremium * itemRiskSurchargeRateOf(item);
148	}
149	
150	/**
151	 * How the office rates the items of one policy. The two quantities are kept
152	 * apart because the office rates its policy-wide terms against one of them and
153	 * not the other: the policy base premium is their rating basis, while item risk
154	 * surcharges ride on top of it untouched by any policy-wide term.
155	 */
156	interface ItemRating {
157	  policyBasePremium: number;
158	  itemRiskSurcharges: number;
159	}
160	
161	/**
162	 * The item side of the premium: it depends on the items alone and knows nothing
163	 * of who brings them.
164	 */
165	function itemRatingOf(items: Item[]): ItemRating {
166	  const itemBasePremiums = groupAlikeItems(items).flatMap(itemBasePremiumsOf);
167	  return {
168	    policyBasePremium: itemBasePremiums.reduce((total, { basePremium }) => total + basePremium, 0),
169	    itemRiskSurcharges: itemBasePremiums.reduce(
170	      (total, itemBasePremium) => total + itemRiskSurchargeOf(itemBasePremium),
171	      0,
172	    ),
173	  };
174	}
175	
176	const LOYALTY_DISCOUNT_RATE = -0.2;
177	const LOYALTY_YEARS = 2;
178	
179	/** The office calls a customer long-standing after 2 years of business. */
180	function isLongStandingCustomer(customer: Customer): boolean {
181	  return customer.yearsWithMHPCO >= LOYALTY_YEARS;
182	}
183	
184	/**
185	 * Everything the office knows when it rates the policy-wide terms of one
186	 * contract: the customer it is writing for, and its own history of contracts
187	 * already written for them. Terms are earned by either, so a clause of the
188	 * office's schedule is rated against the pair rather than against one of them.
189	 */
190	interface PolicyCircumstances {
191	  customer: Customer;
192	  contractsAlreadyWritten: number;
193	}
194	
195	/**
196	 * The office grants its follow-up discount on each contract it writes for a
197	 * customer after their first, so the term is earned by the contracts already
198	 * written rather than by the customer's record.
199	 */
200	function isFollowUpContract({ contractsAlreadyWritten }: PolicyCircumstances): boolean {
201	  return contractsAlreadyWritten > 0;
202	}
203	
204	/**
205	 * One clause of the office's schedule of policy-wide terms: the circumstances it
206	 * looks for in the contract before it, and the rate it then applies to the policy
207	 * base premium. Surcharges carry a positive rate, discounts a negative one -- the
208	 * office's own arithmetic, which adds its policy-wide rates together.
209	 */
210	interface PolicyModifierClause {
211	  appliesTo: (circumstances: PolicyCircumstances) => boolean;
212	  modifierRate: number;
213	}
214	
215	/**
216	 * Each quoted item is a first insurance whatever the customer's history, so the
217	 * office's initial assessment is earned by no record and withheld from none --
218	 * the one scheduled term whose circumstances are always met.
219	 */
220	const FIRST_INSURANCE_SURCHARGE_RATE = 0.1;
221	
222	const FOLLOW_UP_CONTRACT_DISCOUNT_RATE = -0.15;
223	
224	/**
225	 * The office's schedule of policy-wide terms: the initial assessment it levies on
226	 * every contract it writes, what a long-standing record entitles the customer to,
227	 * and what the standing of this contract in their history grants them.
228	 */
229	const POLICY_MODIFIER_CLAUSES: PolicyModifierClause[] = [
230	  { appliesTo: () => true, modifierRate: FIRST_INSURANCE_SURCHARGE_RATE },
231	  {
232	    appliesTo: ({ customer }) => isLongStandingCustomer(customer),
233	    modifierRate: LOYALTY_DISCOUNT_RATE,
234	  },
235	  { appliesTo: isFollowUpContract, modifierRate: FOLLOW_UP_CONTRACT_DISCOUNT_RATE },
236	];
237	
238	/**
239	 * Every policy-wide term the office rates on the policy base premium -- the sum of
240	 * all item base premiums -- never on a single item: whichever scheduled terms the
241	 * circumstances of this contract earn, the office adding their rates together.
242	 */
243	function policyModifierRateOf(circumstances: PolicyCircumstances): number {
244	  return POLICY_MODIFIER_CLAUSES.filter((clause) => clause.appliesTo(circumstances)).reduce(
245	    (rate, clause) => rate + clause.modifierRate,
246	    0,
247	  );
248	}
249	
250	/**
251	 * What the items and the contract's circumstances come to before the office writes
252	 * the figure down: what the items themselves are worth, adjusted by the policy-wide
253	 * terms the circumstances earn, with the processing fee added at the very end. Kept
254	 * as an exact fraction -- the office rounds the premium and nothing on the way to it.
255	 */
256	function exactPolicyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
257	  const { policyBasePremium, itemRiskSurcharges } = itemRating;
258	  const modifierRate = policyModifierRateOf(circumstances);
259	  return (
260	    policyBasePremium + itemRiskSurcharges + policyBasePremium * modifierRate + PROCESSING_FEE
261	  );
262	}
263	
264	/**
265	 * A premium is money owed to the office, so rounding it to whole G in the office's
266	 * own favour means rounding up. (The office's other rounded amount, a payout, is
267	 * money it hands out, and its favour points the other way there.)
268	 */
269	function premiumRoundedInMHPCOsFavour(exactPremium: number): number {
270	  return Math.ceil(exactPremium);
271	}
272	
273	/**
274	 * The premium the office charges for covering those items under this contract: what
275	 * the terms come to, rounded to whole G in the office's favour. The office quotes
276	 * whole G, so rounding is part of the premium it decides on and not a later dressing
277	 * up of the figure.
278	 */
279	function policyPremiumOf(itemRating: ItemRating, circumstances: PolicyCircumstances): number {
280	  return premiumRoundedInMHPCOsFavour(exactPolicyPremiumOf(itemRating, circumstances));
281	}
282	
283	/**
284	 * The office as a going concern: it serves one customer for the length of a
285	 * scenario and remembers the contracts it has already written for them, because
286	 * its follow-up discount depends on that history.
287	 */
288	export class ClaimOffice {
289	  private contractsWritten = 0;
290	
291	  constructor(private readonly customer: Customer) {}
292	
293	  quote(items: Item[]): number {
294	    const premium = policyPremiumOf(itemRatingOf(items), {
295	      customer: this.customer,
296	      contractsAlreadyWritten: this.contractsWritten,
297	    });
298	    this.contractsWritten += 1;
299	    return premium;
300	  }
301	}
302	
303	/** A customer's first and only contract with the office. */
304	export function quote(customer: Customer, items: Item[]): number {
305	  return new ClaimOffice(customer).quote(items);
306	}
307

1	import { describe, expect, it } from "vitest";
2	import { ClaimOffice, quote } from "./claim-office.js";
3	
4	describe("MHPCO Claim Office", () => {
5	  // --- Base premiums per item type (parallel price-list catalogue) ---
6	  it("quotes an empty item list as 5 G (processing fee only)", () => {
7	    expect(quote({ yearsWithMHPCO: 0 }, [])).toBe(5);
8	  });
9	  it("quotes a single plain sword (100 G base + 10 G first insurance + 5 G fee = 115 G)", () => {
10	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
11	  });
12	  it("quotes a single plain amulet (60 G base + 6 G first insurance + 5 G fee = 71 G)", () => {
13	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "amulet" }])).toBe(71);
14	  });
15	  it("quotes a single plain staff (80 G base + 8 G first insurance + 5 G fee = 93 G)", () => {
16	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "staff" }])).toBe(93);
17	  });
18	  it("quotes a single plain potion (40 G base + 4 G first insurance + 5 G fee = 49 G)", () => {
19	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "potion" }])).toBe(49);
20	  });
21	  it("quotes a single rune (25 G base + 2.5 G first insurance + 5 G fee = 32.5 G, rounded up to 33 G)", () => {
22	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }])).toBe(33);
23	  });
24	  it("quotes a single moonstone (25 G base + 2.5 G first insurance + 5 G fee = 32.5 G, rounded up to 33 G)", () => {
25	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "moonstone" }])).toBe(33);
26	  });
27	
28	  // --- Building block of 3 alike components ---
29	  it("quotes 2 runes at 50 G base premium (no block) -- 60 G total", () => {
30	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "rune" }, { type: "rune" }])).toBe(60);
31	  });
32	  it("quotes 3 runes at 60 G base premium (block applies) -- 71 G total", () => {
33	    const threeRunes = [{ type: "rune" }, { type: "rune" }, { type: "rune" }];
34	    expect(quote({ yearsWithMHPCO: 0 }, threeRunes)).toBe(71);
35	  });
36	  it("quotes 4 runes at 100 G base premium (no block -- block requires exactly 3) -- 115 G total", () => {
37	    const fourRunes = Array.from({ length: 4 }, () => ({ type: "rune" }));
38	    expect(quote({ yearsWithMHPCO: 0 }, fourRunes)).toBe(115);
39	  });
40	  it("quotes 7 runes at 175 G base premium (no block -- 7 is not exactly 3) -- 197.5 G, rounded up to 198 G", () => {
41	    const sevenRunes = Array.from({ length: 7 }, () => ({ type: "rune" }));
42	    expect(quote({ yearsWithMHPCO: 0 }, sevenRunes)).toBe(198);
43	  });
44	
45	  // --- "Alike" means exactly the same type, not the same family ---
46	  it("quotes 2 runes + 1 moonstone at 75 G base premium (no block: different types) -- 87.5 G, rounded up to 88 G", () => {
47	    const items = [{ type: "rune" }, { type: "rune" }, { type: "moonstone" }];
48	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(88);
49	  });
50	  it("quotes 3 runes + 3 moonstones at 120 G base premium (two separate blocks of the same type) -- 137 G total", () => {
51	    const runes = Array.from({ length: 3 }, () => ({ type: "rune" }));
52	    const moonstones = Array.from({ length: 3 }, () => ({ type: "moonstone" }));
53	    expect(quote({ yearsWithMHPCO: 0 }, [...runes, ...moonstones])).toBe(137);
54	  });
55	
56	  // --- Item-specific modifiers ---
57	  it("adds a 50 % curse surcharge to a cursed sword's base premium -- 100 G + 50 G curse + 10 G first insurance + 5 G fee = 165 G", () => {
58	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", cursed: true }])).toBe(165);
59	  });
60	  it("adds a 30 % high-enchantment surcharge to a sword with enchantment 5 (threshold met) -- 145 G", () => {
61	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 5 }])).toBe(145);
62	  });
63	  it("adds no high-enchantment surcharge to a sword with enchantment 4 (below threshold) -- 115 G", () => {
64	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword", enchantment: 4 }])).toBe(115);
65	  });
66	  it("adds both curse and high-enchantment surcharges to a cursed sword with enchantment 5 -- 195 G", () => {
67	    const sword = { type: "sword", cursed: true, enchantment: 5 };
68	    expect(quote({ yearsWithMHPCO: 0 }, [sword])).toBe(195);
69	  });
70	  it("applies item-specific surcharges only to the affected item: cursed sword + plain amulet -> 210 G before policy modifiers and fee, 231 G in total", () => {
71	    const items = [{ type: "sword", cursed: true }, { type: "amulet" }];
72	    expect(quote({ yearsWithMHPCO: 0 }, items)).toBe(231);
73	  });
74	
75	  // --- Policy-wide modifiers ---
76	  it("applies the 20 % loyalty discount to the policy base premium for a customer with exactly 2 years with MHPCO -- 95 G", () => {
77	    expect(quote({ yearsWithMHPCO: 2 }, [{ type: "sword" }])).toBe(95);
78	  });
79	  it("applies no loyalty discount for a customer with 1 year with MHPCO -- 115 G", () => {
80	    expect(quote({ yearsWithMHPCO: 1 }, [{ type: "sword" }])).toBe(115);
81	  });
82	  it("applies the 10 % first-insurance surcharge on the policy base premium -- plain sword 115 G", () => {
83	    expect(quote({ yearsWithMHPCO: 0 }, [{ type: "sword" }])).toBe(115);
84	  });
85	  it("applies the 15 % follow-up-contract discount to every quote after the customer's first -- second plain sword quote 100 G", () => {
86	    const office = new ClaimOffice({ yearsWithMHPCO: 0 });
87	    office.quote([{ type: "sword" }]);
88	    expect(office.quote([{ type: "sword" }])).toBe(100);
89	  });
90	  it("applies the first-insurance surcharge to a follow-up contract too (each quoted item is a first insurance) -- 160 G", () => {
91	    const office = new ClaimOffice({ yearsWithMHPCO: 3 });
92	    office.quote([{ type: "amulet" }]);
93	    const sword = { type: "sword", material: "steel", enchantment: 7, cursed: true };
94	    expect(office.quote([sword])).toBe(160);
95	  });
96	
97	  // --- Premium rounding in MHPCO's favour ---
98	  it("rounds a premium of 197.5 G up to 198 G (MHPCO's favour)", () => {
99	    const sevenRunes = Array.from({ length: 7 }, () => ({ type: "rune" }));
100	    expect(quote({ yearsWithMHPCO: 0 }, sevenRunes)).toBe(198);
101	  });
102	  it("keeps intermediate premium amounts as fractions and rounds only the final premium -- 136.25 G rounds to 137 G, not 136 G", () => {
103	    const office = new ClaimOffice({ yearsWithMHPCO: 2 });
104	    office.quote([{ type: "sword" }]);
105	    const sevenRunes = Array.from({ length: 7 }, () => ({ type: "rune" }));
106	    expect(office.quote(sevenRunes)).toBe(137);
107	  });
108	
109	  // --- Premium integration examples ---
110	  it("quotes a newcomer's cursed steel sword (enchantment 3) as 165 G", () => {
111	    const sword = { type: "sword", material: "steel", enchantment: 3, cursed: true };
112	    expect(quote({ yearsWithMHPCO: 0 }, [sword])).toBe(165);
113	  });
114	  it("quotes a 3-year customer's second contract for a cursed sword (enchantment 7) as 160 G", () => {
115	    const office = new ClaimOffice({ yearsWithMHPCO: 3 });
116	    office.quote([{ type: "staff" }]);
117	    const sword = { type: "sword", material: "steel", enchantment: 7, cursed: true };
118	    expect(office.quote([sword])).toBe(160);
119	  });
120	
121	  // --- Insurance sum and cap ---
122	  it.todo("sets the cap for a single sword policy to 2000 G (2 x 1000 G insurance sum)");
123	  it.todo("sets the cap for a two-sword policy to 4000 G (insurance sum 2000 G)");
124	  it.todo("sets the cap for a sword + amulet policy to 3200 G (insurance sum 1600 G)");
125	  it.todo("sets the cap for a sword + 3 runes policy to 3500 G (insurance sum 1750 G -- block discount does not reduce the sum)");
126	  it.todo("bases the cap on the unmodified insurance value: cursed sword (premium 165 G) still has cap 2000 G");
127	
128	  // --- Standard claim reimbursement ---
129	  it.todo("pays out 400 G for a steel sword with enchantment 3 damaged by 500 G (full reimbursement minus 100 G deductible)");
130	  it.todo("pays out 100 G for a rune damaged by 200 G (no enchantment or material, so no special clause)");
131	
132	  // --- Claim special clauses ---
133	  it.todo("pays out 400 G for a steel sword with enchantment 9 damaged by 1000 G (50 % clause, then deductible)");
134	  it.todo("pays out 700 G for a dragon-material sword with enchantment 5 damaged by 800 G (full reimbursement, then deductible)");
135	  it.todo("pays out 400 G for a dragon-material sword with enchantment 9 damaged by 1000 G (50 % rule wins, then deductible)");
136	  it.todo("pays out 400 G for a dragon-material sword with exactly enchantment 8 damaged by 1000 G (threshold met)");
137	
138	  // --- Deductible per damage event ---
139	  it.todo("applies the 100 G deductible once per damaged item: sword 500 G + amulet 300 G -> payout 600 G");
140	  it.todo("treats two sword damage entries on a two-sword policy as separate damages, each with its own deductible");
141	
142	  // --- Payout rounding in MHPCO's favour ---
143	  it.todo("rounds a payout of 350.5 G down to 350 G (MHPCO's favour)");
144	
145	  // --- Cap exhaustion across successive claims ---
146	  it.todo("reports remainingCap 600 G after a first 1500 G claim on a sword policy (payout 1400 G)");
147	  it.todo("limits a second 1500 G claim to the remaining cap: payout 600 G, remainingCap 0 G");
148	
149	  // --- Rejections (observable contract: the domain throws an Error; the CLI exits non-zero and writes the message to stderr) ---
150	  it.todo("throws an Error when a quote contains an unknown item type (e.g. broomstick)");
151	  it.todo("throws an Error when a claim damages an item type that is not part of the policy (amulet damaged, only a sword insured)");
152	  it.todo("throws an Error when a claim damages an unknown item type");
153	  it.todo("throws an Error when a claim contains more damage entries of a type than the policy covers (two sword damages, one sword insured)");
154	  it.todo("throws an Error when a claim contains a damage entry with a negative amount (-200)");
155	
156	  // --- CLI adapter (src/cli.ts): JSON in, JSON out ---
157	  it.todo("CLI reads the schema example scenario from stdin and writes {results:[{premium},{payout,remainingCap}]} to stdout");
158	  it.todo("CLI processes steps sequentially so a claim step resolves its policy by the quote step's zero-based index");
159	  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an unknown quote item type, writing no results to stdout");
160	  it.todo("CLI exits with a non-zero status and writes an error description to stderr for an invalid claim");
161	});
