const PROCESSING_FEE = 5;

/**
 * How the office classes an item on its price list. Main items each have a row of
 * their own; components share a single uniform rate, and the office's
 * building-block offer is written for components alone.
 */
type PriceListClass = "main item" | "component";

/** One row of the MHPCO price list: what the office charges to insure one such item. */
interface PriceListEntry {
  class: PriceListClass;
  basePremium: number;
}

const COMPONENT_BASE_PREMIUM = 25;

/**
 * The MHPCO price list, as posted at the counter: every kind of item the office
 * recognises, and what it charges for one of them. An item type absent from the
 * list is one the office does not insure.
 */
const PRICE_LIST: Record<string, PriceListEntry> = {
  sword: { class: "main item", basePremium: 100 },
  amulet: { class: "main item", basePremium: 60 },
  staff: { class: "main item", basePremium: 80 },
  potion: { class: "main item", basePremium: 40 },
  rune: { class: "component", basePremium: COMPONENT_BASE_PREMIUM },
  moonstone: { class: "component", basePremium: COMPONENT_BASE_PREMIUM },
};

/** The price list's row for the given item type. */
function priceListEntryOf(type: string): PriceListEntry {
  return PRICE_LIST[type];
}

function isComponentType(type: string): boolean {
  return priceListEntryOf(type).class === "component";
}

/** The price-list base premium for one item of the given type. */
function catalogueBasePremiumOf(type: string): number {
  return priceListEntryOf(type).basePremium;
}

const BLOCK_SIZE = 3;
const BLOCK_BASE_PREMIUM = 60;

/** A policy's items of one and the same type -- what the office calls "alike". */
interface AlikeItems {
  type: string;
  items: Item[];
}

/**
 * The office groups a policy's items into groups of alike items, because its
 * building-block offer is priced per group rather than per item. "Alike" means
 * the same item type.
 */
function groupAlikeItems(items: Item[]): AlikeItems[] {
  const groups = new Map<string, AlikeItems>();
  for (const item of items) {
    const group = groups.get(item.type);
    if (group === undefined) {
      groups.set(item.type, { type: item.type, items: [item] });
    } else {
      group.items.push(item);
    }
  }
  return [...groups.values()];
}

/**
 * A building block of exactly 3 alike components is offered at a special base
 * premium instead of the catalogue rate; any other count is priced per component.
 */
function isBuildingBlock({ type, items }: AlikeItems): boolean {
  return isComponentType(type) && items.length === BLOCK_SIZE;
}

/** Without an offer, the office simply charges the catalogue rate for every item. */
function catalogueRateBasePremiumOf({ type, items }: AlikeItems): number {
  return items.length * catalogueBasePremiumOf(type);
}

/** What the office charges for one group of alike items covered by the same policy. */
function alikeItemsBasePremiumOf(alikeItems: AlikeItems): number {
  return isBuildingBlock(alikeItems)
    ? BLOCK_BASE_PREMIUM
    : catalogueRateBasePremiumOf(alikeItems);
}

const HIGH_ENCHANTMENT_LEVEL = 5;

function isCursed(item: Item): boolean {
  return item.cursed === true;
}
